import React from 'react'
import { CardContainer } from './styles'
import {
  FiTrash2,
  FiLock,
  FiUnlock,
  FiStar,
  FiType,
  FiMic,
  FiVolume2,
  FiVolumeX,
  FiArchive,
  FiCpu,
  FiRotateCcw,
} from 'react-icons/fi'

import { UserAuth } from '../../contexts/AuthContext'
import { executeAI } from '../../services/aiService'
import { saveOpenAIKey, getOpenAIKey } from '../../services/openAIKeyService'
import { RxDividerVertical } from 'react-icons/rx'
import { MdOutlineColorLens } from 'react-icons/md'
import { FaStar } from 'react-icons/fa'
import { IoMdArrowDropdown, IoMdArrowDropleft } from 'react-icons/io'
import { FiSend } from 'react-icons/fi'
import { MdOutlineContentCopy } from 'react-icons/md'
import { IoMdAddCircleOutline } from 'react-icons/io'
import { FiTag } from 'react-icons/fi'

import { isJsonString } from '../../utils'
import { formatDate, limitInputLength } from '../../utils'
import rehypeRaw from 'rehype-raw'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import remarkFrontmatter from 'remark-frontmatter'
import remarkEmoji from 'remark-emoji'
import remarkMath from 'remark-math'
import rehypeKatex from 'rehype-katex'
import remarkToc from 'remark-toc'
import remarkBreaks from 'remark-breaks'
import stringWidth from 'string-width'
import FloatingColorPicker from '../FloatingColorPicker'
import { IconButton } from '../../styles/global'

import { useSpeechRecognition } from '../../hooks/useSpeechRecognition'
import { useTextToSpeech } from '../../hooks/useTextToSpeech'
import FloatingTemplatePicker from '../FloatingTemplatePicker'

import { templateOptions, TemplateOption } from '../../utils'
import { processMacros } from '../../services/templateMacros'
import { renderTemplate, executeExpression } from '../../services/templateEngine'

import { getLocationData } from '../../services/locationService'

interface ButtonCommandProps {
  label: string
  expression: string
  onExecute: (expression: string) => void
}

const ButtonCommand: React.FC<ButtonCommandProps> = ({ label, expression, onExecute }) => {
  return (
    <button className="markdownButton" onClick={() => onExecute(expression)}>
      {label}
    </button>
  )
}

interface ICardProps {
  id: string
  number: number
  date: string
  content: string
  onDeleteCard: any
  onChangeContent: any
  tags: string[]
}

export const defaultContent = {
  title: '',
  type: 'record',
  tags: [],
  text: '',
  color: '#fff',
  locked: false,
  pinned: false,
  collapsed: false,
}

const noteColors = [
  '#F8F9FA',
  '#CED4DA',
  '#FFF4B5',
  '#FFDCC8',
  '#FFCDD2',
  '#FADCE6',
  '#DCCCFB',
  '#BBDEFB',
  '#C8E6C9',
  '#B2DFDB',
  '#F3E5C8',
  '#D7CCC8',
]

export const Card: React.FC<ICardProps> = ({
  id,
  date,
  content,
  onDeleteCard,
  onChangeContent,
  tags,
}) => {
  const [temperature, setTemperature] = React.useState('')
  const [weather, setWeather] = React.useState('')
  const [location, setLocation] = React.useState({ city: '', country: '' })
  const { listening, transcript, startListening, stopListening } = useSpeechRecognition()
  const { speak, speaking, stopSpeaking } = useTextToSpeech()
  const [editingContent, setEditingContent] = React.useState(false)
  const [showToolBox, setShowToolBox] = React.useState(false)
  const [showColorPicker, setShowColorPicker] = React.useState(false)
  const [showTemplatePicker, setShowTemplatePicker] = React.useState(false)
  const [cursorPosition, setCursorPosition] = React.useState<number | null>(null)
  const textareaRef = React.useRef<HTMLTextAreaElement>(null)
  const markdownRef = React.useRef<HTMLDivElement>(null)
  const tagPickerRef = React.useRef<HTMLDivElement>(null)
  const colorPickerRef = React.useRef<HTMLDivElement>(null)
  const templatePickerRef = React.useRef<HTMLDivElement>(null)
  const [showTagPicker, setShowTagPicker] = React.useState(false)
  const [creatingTag, setCreatingTag] = React.useState(false)
  const [newTagName, setNewTagName] = React.useState('')
  const [isMobile, setIsMobile] = React.useState(window.innerWidth < 1260)
  const { user } = UserAuth()

  React.useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 1260)
    }

    window.addEventListener('resize', handleResize)

    return () => window.removeEventListener('resize', handleResize)
  }, [])

  React.useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node

      if (tagPickerRef.current && !tagPickerRef.current.contains(target)) {
        setShowTagPicker(false)
        setCreatingTag(false)
      }

      if (colorPickerRef.current && !colorPickerRef.current.contains(target)) {
        setShowColorPicker(false)
      }

      if (templatePickerRef.current && !templatePickerRef.current.contains(target)) {
        setShowTemplatePicker(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [])

  const archiveNote = () => {
    const updatedTags = objContent.tags.includes('archive')
      ? objContent.tags.filter((tag: string) => tag !== 'archive')
      : [...objContent.tags.filter((tag: string) => tag !== 'trash'), 'archive']

    onChangeContent(
      id,
      JSON.stringify({
        ...objContent,
        tags: Array.from(new Set(updatedTags)),
      })
    )
  }

  const parsed = isJsonString(content) ? JSON.parse(content) : { ...defaultContent, text: content }

  const objContent = {
    ...defaultContent,
    ...parsed,
    tags: Array.from(new Set([...(parsed.tags || [])])),
  }
  const [value, setValue] = React.useState(objContent.text || '')
  const [history, setHistory] = React.useState<string[]>([])
  const [aiLoading, setAiLoading] = React.useState(false)

  const pushHistory = React.useCallback((currentText: string) => {
    setHistory((h) => {
      if (h[h.length - 1] === currentText) {
        return h
      }

      return [...h, currentText]
    })
  }, [])

  const hasTag = (tag: string) => objContent.tags?.includes(tag)

  const toggleTag = (tag: string) => {
    const tags = Array.from(
      new Set(
        hasTag(tag) ? objContent.tags.filter((t: string) => t !== tag) : [...objContent.tags, tag]
      )
    )

    onChangeContent(
      id,
      JSON.stringify({
        ...objContent,
        tags,
      })
    )
  }

  const createTag = (name: string) => {
    const normalized = name.trim().toLowerCase()

    if (!normalized) {
      return
    }

    toggleTag(normalized)

    setNewTagName('')
    setCreatingTag(false)
  }

  const closeToolBox = () => {
    setShowToolBox(false)
    setShowColorPicker(false)
    setShowTemplatePicker(false)
  }

  React.useEffect(() => {
    setValue(objContent.text || '')
  }, [content])

  const formatTag = (tag: string) => tag.replace(/\b\w/g, (c) => c.toUpperCase())

  React.useEffect(() => {
    if (!editingContent || !textareaRef.current || cursorPosition === null) {
      return
    }

    const textarea = textareaRef.current

    textarea.focus()
    textarea.setSelectionRange(cursorPosition, cursorPosition)

    requestAnimationFrame(() => {
      const mirror = document.createElement('div')

      const style = window.getComputedStyle(textarea)

      mirror.style.position = 'absolute'
      mirror.style.visibility = 'hidden'
      mirror.style.whiteSpace = 'pre-wrap'
      mirror.style.wordWrap = 'break-word'
      mirror.style.font = style.font
      mirror.style.lineHeight = style.lineHeight
      mirror.style.padding = style.padding
      mirror.style.width = `${textarea.clientWidth}px`

      mirror.textContent = textarea.value.substring(0, cursorPosition)

      document.body.appendChild(mirror)

      const cursorTop = mirror.offsetHeight

      document.body.removeChild(mirror)

      const textareaTop = textarea.getBoundingClientRect().top + window.scrollY

      window.scrollTo({
        top: textareaTop + cursorTop - window.innerHeight / 2,
        behavior: 'smooth',
      })
    })
  }, [editingContent, cursorPosition])

  const findBestCursorPosition = (clickedText: string, markdown: string) => {
    const cleanText = clickedText
      .replace(/[█░]+/g, '')
      .replace(/\d+(?:\.\d+)?%?/g, '')
      .replace(/\s+/g, ' ')
      .trim()

    if (!cleanText) {
      return markdown.length
    }

    const words = cleanText.split(' ')

    for (let size = Math.min(words.length, 8); size >= 2; size--) {
      for (let start = 0; start <= words.length - size; start++) {
        const phrase = words.slice(start, start + size).join(' ')

        const pos = markdown.indexOf(phrase)

        if (pos >= 0) {
          return pos
        }
      }
    }

    for (const word of words) {
      if (word.length < 4) {
        continue
      }

      const pos = markdown.indexOf(word)

      if (pos >= 0) {
        return pos
      }
    }

    return markdown.length
  }

  const setTemplate = (option: TemplateOption) => {
    pushHistory(value)
    closeToolBox()
    let text = option.text.replace(/\\\$\{/g, '${')
    text = localProcessMacros(text)

    if (!objContent.locked) {
      const mergedTags = Array.from(new Set([...(objContent.tags || []), ...(option.tags || [])]))

      onChangeContent(
        id,
        JSON.stringify({
          ...objContent,
          collapsed: false,
          color: option.color,
          text: text,
          title: localProcessMacros(option.title),
          tags: mergedTags,
        })
      )
      setValue(text)
    }
  }

  const processAndDisplayMarkdown = (text: string) =>
    renderTemplate(
      text,
      {
        temperature,
        weather,
        city: location.city,
        country: location.country,
      },
      isMobile
    )

  const handleExecuteExpression = (expression: string) => {
    pushHistory(value)
    const newText = executeExpression(value, expression, {
      temperature,
      weather,
      city: location.city,
      country: location.country,
    })

    setValue(newText)

    onChangeContent(
      id,
      JSON.stringify({
        ...objContent,
        text: newText,
      })
    )
  }

  const trashNote = () => {
    if (hasTag('trash')) {
      onDeleteCard(id, true)
      return
    }

    const updatedTags = Array.from(
      new Set([...objContent.tags.filter((tag: string) => tag !== 'archive'), 'trash'])
    )

    onChangeContent(
      id,
      JSON.stringify({
        ...objContent,
        tags: updatedTags,
      })
    )
  }

  const localProcessMacros = (text: string) =>
    processMacros(text, {
      weather,
      temperature,
      city: location.city,
      country: location.country,
    })

  const onChangeMarkdownContent = (id: string, newText: string) => {
    const processedText = localProcessMacros(newText)

    onChangeContent(
      id,
      JSON.stringify({
        ...objContent,
        text: processedText,
      })
    )

    setValue(processedText)
  }

  const copyFormattedContent = async () => {
    if (!markdownRef.current) {
      return
    }

    const html = markdownRef.current.innerHTML
    const text = markdownRef.current.innerText

    await navigator.clipboard.write([
      new ClipboardItem({
        'text/html': new Blob([html], { type: 'text/html' }),
        'text/plain': new Blob([text], { type: 'text/plain' }),
      }),
    ])
  }

  const undoLastChange = () => {
    const previous = history[history.length - 1]

    if (!previous) {
      return
    }

    setHistory((h) => h.slice(0, -1))

    setValue(previous)

    onChangeContent(
      id,
      JSON.stringify({
        ...objContent,
        text: previous,
      })
    )
  }

  const handleAI = async () => {
    if (!user?.uid) {
      alert('User not authenticated')
      return
    }

    let apiKey = await getOpenAIKey(user.uid)

    if (!apiKey) {
      apiKey =
        window.prompt('OpenAI API Key not configured.\n\nEnter your OpenAI API Key:')?.trim() || ''

      if (!apiKey) {
        return
      }

      await saveOpenAIKey(user.uid, apiKey)
    }

    const instruction = window.prompt(
      'Examples:\n\nFix grammar\nSummarize\nRewrite professionally\nTranslate to Portuguese'
    )

    if (!instruction?.trim()) {
      return
    }

    setAiLoading(true)

    try {
      pushHistory(value)

      const textarea = textareaRef.current

      if (textarea && textarea.selectionStart !== textarea.selectionEnd) {
        const start = textarea.selectionStart
        const end = textarea.selectionEnd

        const selectedText = value.substring(start, end)

        const result = await executeAI(user.uid, instruction, selectedText, apiKey)

        const updated = value.substring(0, start) + result + value.substring(end)

        setValue(updated)

        onChangeContent(
          id,
          JSON.stringify({
            ...objContent,
            text: updated,
          })
        )

        return
      }

      const result = await executeAI(user.uid, instruction, value, apiKey)

      const updated = value + '\n\n' + result

      setValue(updated)

      onChangeContent(
        id,
        JSON.stringify({
          ...objContent,
          text: updated,
        })
      )
    } catch (error) {
      console.error(error)

      alert(error instanceof Error ? error.message : 'AI request failed')
    } finally {
      setAiLoading(false)
    }
  }

  React.useEffect(() => {
    getLocationData()
      .then((data) => {
        setTemperature(data.temperature)

        setWeather(data.weather)

        setLocation({
          city: data.city,
          country: data.country,
        })
      })
      .catch(console.error)
  }, [])

  React.useEffect(() => {
    if (!listening && transcript) {
      pushHistory(value)

      const updated = value + transcript

      onChangeContent(
        id,
        JSON.stringify({
          ...objContent,
          text: updated,
        })
      )

      setValue(updated)
    }
  }, [listening, transcript])

  const isLocked = objContent.locked

  return (
    <CardContainer key={id}>
      <div className="ContentContainer" style={{ backgroundColor: objContent.color || '#eee' }}>
        <header className="header">
          <strong className="titleBox">
            {hasTag('favorite') ? (
              <IconButton
                disabled={isLocked}
                title="Remove favorite"
                onClick={() => toggleTag('favorite')}
              >
                <FaStar />
              </IconButton>
            ) : (
              <IconButton
                disabled={isLocked}
                title="Add favorite"
                onClick={() => toggleTag('favorite')}
              >
                <FiStar />
              </IconButton>
            )}
            {!showToolBox ? (
              <span
                className="title"
                title="Note name"
                role="textbox"
                contentEditable={!objContent.locked}
                suppressContentEditableWarning
                data-placeholder="🙋 Give me a name"
                onInput={(e) => limitInputLength(e, 40)}
                onBlur={(e) =>
                  onChangeContent(
                    id,
                    JSON.stringify({
                      ...objContent,
                      title: localProcessMacros(e.target.innerText),
                    })
                  )
                }
              >
                {objContent.title}
              </span>
            ) : (
              <span className="title"></span>
            )}
          </strong>

          <span className="toolbox">
            {speaking ? (
              <IconButton title="Stop hearing note" onClick={stopSpeaking}>
                <FiVolumeX color={'#2563eb'} />
              </IconButton>
            ) : (
              <IconButton title="Hear note" onClick={() => speak(value)}>
                <FiVolume2 />
              </IconButton>
            )}
            <IconButton title="Copy note" onClick={copyFormattedContent}>
              <MdOutlineContentCopy />
            </IconButton>
            {objContent.locked ? (
              <IconButton
                title="Unlock note"
                onClick={() =>
                  onChangeContent(id, JSON.stringify({ ...objContent, locked: false }))
                }
              >
                <FiLock color={isLocked ? '#2563eb' : undefined} />
              </IconButton>
            ) : (
              <IconButton
                title="Lock note"
                onClick={() => onChangeContent(id, JSON.stringify({ ...objContent, locked: true }))}
              >
                <FiUnlock />
              </IconButton>
            )}
            {objContent.collapsed ? (
              <IconButton
                title="Expand note"
                onClick={() =>
                  onChangeContent(id, JSON.stringify({ ...objContent, collapsed: false }))
                }
              >
                <IoMdArrowDropleft />
              </IconButton>
            ) : (
              <IconButton
                title="Collapse note"
                onClick={() =>
                  onChangeContent(id, JSON.stringify({ ...objContent, collapsed: true }))
                }
              >
                <IoMdArrowDropdown />
              </IconButton>
            )}
          </span>
        </header>

        {!objContent.collapsed ? (
          <>
            {editingContent ? (
              <textarea
                ref={textareaRef}
                className="reactMarkDown"
                placeholder={`* ❓ What do you have for today?


<markdown editor>`}
                onFocus={(e) => {
                  const el = e.currentTarget
                  el.style.height = 'auto'
                  el.style.height = `${el.scrollHeight}px`
                }}
                onChange={(e) => {
                  const el = e.currentTarget

                  el.style.height = `${el.scrollHeight}px`

                  setValue(e.target.value)
                }}
                autoFocus
                value={value || ''}
                onBlur={(e) => {
                  const related = e.relatedTarget as HTMLElement | null
                  if (related?.dataset?.keepeditor === 'true') {
                    return
                  }

                  onChangeMarkdownContent(id, value)
                  setEditingContent(false)
                }}
              />
            ) : (
              <div
                ref={markdownRef}
                className="reactMarkDown"
                onClick={(e) => {
                  if (objContent.locked) {
                    return
                  }

                  pushHistory(value)

                  const target = e.target as HTMLElement

                  const clickedText = target.innerText || target.textContent || ''

                  const pos = findBestCursorPosition(clickedText, value)

                  setCursorPosition(pos)
                  setEditingContent(true)
                }}
              >
                <ReactMarkdown
                  rehypePlugins={[rehypeRaw]}
                  components={{
                    button(props) {
                      const expression = decodeURIComponent(
                        String((props.node as any)?.properties?.dataExpression ?? '')
                      )
                      return (
                        <ButtonCommand
                          label={String(props.children)}
                          expression={expression}
                          onExecute={handleExecuteExpression}
                        />
                      )
                    },
                  }}
                  children={processAndDisplayMarkdown(value || '* ❓ What do you have for today?')}
                  remarkPlugins={[
                    [
                      remarkEmoji,
                      {
                        padSpaceAfter: false,
                        emoticon: true,
                      },
                    ],
                    [remarkToc, { tight: true, ordered: true }],
                    [remarkGfm, { stringLength: stringWidth }],
                    remarkMath,
                    rehypeKatex,
                    remarkBreaks,
                    remarkFrontmatter,
                  ]}
                />
              </div>
            )}
            <footer className="footer">
              <span className="footbox">
                <span
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '8px',
                  }}
                >
                  <div className="tagList">
                    <span className="date">{formatDate(date)}</span>
                    {objContent.tags.map((tag: string) => (
                      <span
                        key={tag}
                        className="tagChip"
                        onClick={() => !isLocked && toggleTag(tag)}
                      >
                        {formatTag(tag)}
                      </span>
                    ))}
                  </div>

                  <div ref={tagPickerRef} className="tagPicker">
                    {!isLocked && (
                      <span
                        className="tagPickerButton"
                        onClick={() => setShowTagPicker(!showTagPicker)}
                      >
                        <IoMdAddCircleOutline />
                      </span>
                    )}

                    {showTagPicker && (
                      <div className="tagDropdown">
                        {tags.map((tag) => (
                          <button
                            key={tag}
                            className={`tagOption ${hasTag(tag) ? 'selected' : ''}`}
                            onClick={() => toggleTag(tag)}
                          >
                            <>
                              <FiTag />
                              <span>{formatTag(tag)}</span>
                            </>
                          </button>
                        ))}

                        {!creatingTag ? (
                          <button className="newTagButton" onClick={() => setCreatingTag(true)}>
                            <>
                              <FiTag />
                              New Tag
                            </>
                          </button>
                        ) : (
                          <input
                            autoFocus
                            className="newTagInput"
                            placeholder="Tag name..."
                            value={newTagName}
                            onChange={(e) => setNewTagName(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter') {
                                createTag(newTagName)
                              }

                              if (e.key === 'Escape') {
                                setCreatingTag(false)
                                setNewTagName('')
                              }
                            }}
                            onBlur={() => {
                              if (newTagName.trim()) {
                                createTag(newTagName)
                              } else {
                                setCreatingTag(false)
                              }
                            }}
                          />
                        )}
                      </div>
                    )}
                  </div>
                </span>
                <span className="toolbox">
                  <IconButton
                    disabled={isLocked}
                    title="Change note background color"
                    onClick={() => setShowColorPicker(!showColorPicker)}
                  >
                    <MdOutlineColorLens />
                  </IconButton>

                  <IconButton
                    disabled={isLocked}
                    title="Load template"
                    onClick={() => setShowTemplatePicker(!showTemplatePicker)}
                  >
                    <FiType />
                  </IconButton>
                  <IconButton
                    disabled={isLocked}
                    data-keepeditor="true"
                    title="AI assistant"
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={() => {
                      if (!objContent.locked) {
                        handleAI()
                      }
                    }}
                  >
                    <FiCpu color={aiLoading ? '#2563eb' : undefined} />
                  </IconButton>
                  <IconButton
                    disabled={isLocked}
                    data-keepeditor="true"
                    title="Revert last change"
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={undoLastChange}
                  >
                    <FiRotateCcw />
                  </IconButton>
                  {listening ? (
                    <IconButton disabled={isLocked} title="Stop listening" onClick={stopListening}>
                      <FiSend color={'#2563eb'} />
                    </IconButton>
                  ) : (
                    <IconButton
                      disabled={isLocked}
                      title="Listen note"
                      onClick={() => {
                        if (!objContent.locked) startListening()
                      }}
                    >
                      <FiMic />
                    </IconButton>
                  )}
                  <RxDividerVertical />

                  <IconButton
                    disabled={isLocked}
                    title={hasTag('archive') ? 'Unarchive note' : 'Archive note'}
                    onClick={() => {
                      if (!objContent.locked) archiveNote()
                    }}
                  >
                    <FiArchive color={hasTag('archive') ? '#2563eb' : undefined} />
                  </IconButton>

                  <IconButton
                    disabled={isLocked}
                    title={hasTag('trash') ? 'Delete permanently' : 'Move to trash'}
                    onClick={() => {
                      if (!objContent.locked) {
                        trashNote()
                      }
                    }}
                  >
                    <FiTrash2 color={hasTag('trash') ? '#dc2626' : undefined} />
                  </IconButton>
                </span>
              </span>
            </footer>
          </>
        ) : (
          <></>
        )}

        {showColorPicker && (
          <div ref={colorPickerRef}>
            <FloatingColorPicker
              colors={noteColors}
              onColorClicked={(selectedColor: string) => {
                onChangeContent(
                  id,
                  JSON.stringify({
                    ...objContent,
                    color: selectedColor,
                  })
                )
                setShowColorPicker(false)
              }}
            />
          </div>
        )}
        {showTemplatePicker ? (
          <div ref={templatePickerRef}>
            <FloatingTemplatePicker options={templateOptions} onPicked={setTemplate} />
          </div>
        ) : (
          <></>
        )}
      </div>
    </CardContainer>
  )
}
