import React from 'react'
import { BodyContainer, DataContainer, IconButton } from '../../styles/global'
import { IoMdAddCircleOutline } from 'react-icons/io'
import { MdOutlineClear } from 'react-icons/md'
import { FiStar, FiArchive, FiTrash2 } from 'react-icons/fi'
import { IoMdSearch } from 'react-icons/io'
import { getTags } from '../../utils'
import { Card, defaultContent } from '../../components/Card'
import uuid from 'react-uuid'
import {
  EntryList,
  MenuContainer,
  MenuBarContainer,
  DateContainer,
  ActionsContainer,
  SearchContainer,
  SelectedPage,
} from './styles'
import { database } from '../../services/firebase'
import {
  collection,
  query,
  where,
  getDocs,
  doc,
  addDoc,
  setDoc,
  deleteDoc,
} from 'firebase/firestore'

import { FiLock, FiCopy } from 'react-icons/fi'
import { UserAuth } from '../../contexts/AuthContext'
import { useDashboard } from '../../contexts/DashboardContext'
import { HeaderPortal } from '../../components/HeaderPortal'
import userImg from '../../assets/user.png'
import { FiEye } from 'react-icons/fi'
import { IoMdArrowDropdown, IoMdArrowDropleft } from 'react-icons/io'
import { VerticalBar, TagItem } from '../../components/VerticalBar'
import { BsJournalBookmark } from 'react-icons/bs'
import { FiType } from 'react-icons/fi'

interface IEntry {
  uid: string
  id: string
  content: string
  date: string
  createdAt: string
}

const Dashboard: React.FC = () => {
  const { selectedDate, setSelectedDate } = useDashboard()
  const [searchContent, setSearchContent] = React.useState('')
  const [entries, setEntries] = React.useState<IEntry[]>([])
  const { user, logOut } = UserAuth()
  const startDate = new Date().toISOString().split('T')[0]
  const dateRef = React.useRef<HTMLInputElement>(null)

  const systemTags: TagItem[] = [
    { name: 'all', icon: FiEye, system: true },
    { name: 'favorite', icon: FiStar, system: true },
    { name: 'journal', icon: BsJournalBookmark, system: true },
    { name: 'templates', icon: FiType, system: true },
    { name: 'archive', icon: FiArchive, system: true },
    { name: 'trash', icon: FiTrash2, system: true },
  ]

  const systemTagNames = systemTags.map((tag) => tag.name)

  const availableTags = Array.from(new Set(entries.flatMap((entry) => getTags(entry.content))))
    .filter((tag) => !systemTagNames.includes(tag))
    .sort()

  const pickerTags = Array.from(new Set(['journal', 'templates', ...availableTags])).sort()

  const [selectedTag, setSelectedTag] = React.useState('favorite')

  const isEntryVisible = (entry: IEntry) => {
    const tags = getTags(entry.content)

    if (searchContent.trim() !== '') {
      return entry.content.toLowerCase().includes(searchContent.toLowerCase())
    }

    if (selectedTag === 'all') {
      return !tags.includes('archive') && !tags.includes('trash')
    }

    if (selectedTag === 'archive') {
      return tags.includes('archive')
    }

    if (selectedTag === 'trash') {
      return tags.includes('trash')
    }

    return tags.includes(selectedTag) && !tags.includes('archive') && !tags.includes('trash')
  }

  const handleCopyAllNotes = async () => {
    const visibleEntries = entries.filter(isEntryVisible)

    const text = visibleEntries
      .map((entry) => {
        try {
          const content = JSON.parse(entry.content)
          return [
            `# ${content.title || 'Untitled'}`,
            `Date: ${entry.date}`,
            `Tags: ${(content.tags || []).join(', ')}`,
            '',
            content.text || '',
          ].join('\n')
        } catch {
          return entry.content
        }
      })
      .join('\n\n────────────────────────────\n\n')

    await navigator.clipboard.writeText(text)
  }

  const handleLogout = async () => {
    try {
      await logOut()
    } catch (error) {
      console.log(error)
    }
  }

  const handleDateChanged = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedDate(event.target.value)
  }

  const search = async (value: string) => {
    setSearchContent(value)
  }

  async function handleAddNewEntry(event: any) {
    const tags = selectedTag !== 'all' ? [selectedTag] : []

    const newEntry: IEntry = {
      uid: user.uid,
      id: uuid(),
      content: JSON.stringify({
        ...defaultContent,
        tags,
      }),
      date: selectedDate,
      createdAt: new Date().toISOString(),
    }
    scrollToTop()
    const newEntries = [...entries, newEntry]
    newEntries.sort((a, b) => {
      if (a.date > b.date) return -1
      if (a.date < b.date) return 1
      if (a.createdAt > b.createdAt) return -1
      if (a.createdAt < b.createdAt) return 1
      return 0
    })
    setEntries(newEntries)
    const userDocRef = doc(database, 'users', user.uid)
    const entriesRef = collection(userDocRef, 'entries')
    await addDoc(entriesRef, newEntry)
  }

  async function fetchEntries() {
    const userDocRef = doc(database, 'users', user.uid)
    const entriesRef = collection(userDocRef, 'entries')
    const querySnapshot = await getDocs(entriesRef)
    const entries: IEntry[] = []
    querySnapshot.forEach((doc) => {
      let newEntry = doc.data() as IEntry
      if (!newEntry.createdAt) {
        newEntry.createdAt = newEntry.date
      }
      entries.push(newEntry)
    })
    entries.sort((a, b) => {
      if (a.date > b.date) return -1
      if (a.date < b.date) return 1
      if (a.createdAt > b.createdAt) return -1
      if (a.createdAt < b.createdAt) return 1
      return 0
    })
    setEntries(entries)
  }

  React.useEffect(() => {
    fetchEntries()
  }, [])

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth',
    })
  }

  const handleDeleteEntry = async (id: string, permanent = false) => {
    if (!permanent) {
      const entry = entries.find((e) => e.id === id)

      if (!entry) {
        return
      }

      const content = JSON.parse(entry.content)

      const tags = Array.from(
        new Set([...(content.tags || []).filter((tag: string) => tag !== 'archive'), 'trash'])
      )

      await handleChangeEntry(
        id,
        JSON.stringify({
          ...content,
          tags,
        })
      )

      return
    }

    const newEntries = entries.filter((entry) => entry.id !== id)
    setEntries(newEntries)

    const userDocRef = doc(database, 'users', user.uid)
    const entriesRef = collection(userDocRef, 'entries')
    const userQuery = query(entriesRef, where('id', '==', id))
    const querySnapshot = await getDocs(userQuery)

    querySnapshot.forEach((document) => {
      deleteDoc(doc(database, `users/${user.uid}/entries`, document.id))
    })
  }

  const handleChangeEntry = async (id: string, content: string) => {
    const newEntries = entries.map((entry) =>
      entry.id === id
        ? {
            ...entry,
            content,
          }
        : entry
    )
    setEntries(newEntries)

    const changedEntry = newEntries.find((entry) => entry.id === id)
    if (changedEntry) {
      changedEntry.content = content
      const userDocRef = doc(database, 'users', user.uid)
      const entriesRef = collection(userDocRef, 'entries')
      const userQuery = query(entriesRef, where('id', '==', id))
      const querySnapshot = await getDocs(userQuery)
      querySnapshot.forEach((document) => {
        setDoc(doc(database, `users/${user.uid}/entries`, document.id), changedEntry)
      })
    }
  }

  let count = 0
  const isLoggedIn =
    user !== null &&
    user.displayName !== undefined &&
    user.photoURL !== null &&
    user.photoURL !== undefined

  return (
    <BodyContainer>
      <HeaderPortal>
        {isLoggedIn && (
          <MenuContainer>
            <SelectedPage>
              {searchContent.trim() === ''
                ? selectedTag.charAt(0).toUpperCase() + selectedTag.slice(1)
                : 'Search'}
            </SelectedPage>
            {selectedTag === 'journal' ? (
              <DateContainer>
                <input
                  title="Select date"
                  ref={dateRef}
                  type="date"
                  defaultValue={startDate}
                  onChange={handleDateChanged}
                />
              </DateContainer>
            ) : (
              <></>
            )}

            <SearchContainer>
              <input
                placeholder="Search"
                value={searchContent}
                onChange={(e) => search(e.target.value)}
              />

              <IconButton title="Clear search" onClick={() => setSearchContent('')}>
                <MdOutlineClear />
              </IconButton>
            </SearchContainer>

            <ActionsContainer>
              <IconButton title="Copy all visible notes" onClick={handleCopyAllNotes}>
                <FiCopy />
              </IconButton>
              <IconButton title="Add note" onClick={handleAddNewEntry}>
                <IoMdAddCircleOutline />
              </IconButton>
            </ActionsContainer>
          </MenuContainer>
        )}

        {isLoggedIn && (
          <MenuBarContainer>
            <img
              title="Logout"
              src={user.photoURL ? user.photoURL : userImg}
              onError={({ currentTarget }) => {
                currentTarget.onerror = null
                currentTarget.src = userImg
              }}
              alt="User photograph"
              onClick={() => handleLogout()}
            />
          </MenuBarContainer>
        )}
      </HeaderPortal>
      <DataContainer>
        <EntryList>
          {entries.map((entry) => {
            const visible = isEntryVisible(entry)
            return visible ? (
              <Card
                key={entry.id}
                id={entry.id}
                date={entry.date}
                number={(count = count + 1)}
                content={entry.content}
                onDeleteCard={handleDeleteEntry}
                onChangeContent={handleChangeEntry}
                tags={pickerTags}
              />
            ) : (
              <div key={entry.id} />
            )
          })}
        </EntryList>
      </DataContainer>
      <VerticalBar
        systemTags={systemTags}
        customTags={availableTags}
        selectedTag={selectedTag}
        setSelectedTag={setSelectedTag}
      />
    </BodyContainer>
  )
}

export default Dashboard
